    /**
     * @description 0-9选3个数，三字现
     */
    public function actionTestNum()
    {
        $insertData = [];
        $count = 0;
        $field = ['code'];
        for ($i = 0; $i <= 9; $i++) {
            for ($m = $i + 1; $m <= 9; $m++) {
                if ($m == $i) continue;
                for ($n = $m + 1; $n <= 9; $n++) {
                    if ($m == $n || $n == $i) continue;
                    $insertData[] = [$i . $m . $n];
                    $count++;
                }
            }
        }
        $totalnum = \Yii::$app->db->createCommand()->batchInsert("{{%three_num}}", $field, $insertData)->execute();


        echo '<br>======' . $count . '======' . $totalnum . '=========';
    }

