    public static function dealTime($a)
    {
        $time = strtotime($a);
        return $time;
        $year = substr($a, 0, 4);
        $month = substr($a, 4, 2);
        $day = substr($a, 6, 2);
        $hour = substr($a, 8, 2);
        $min = substr($a, 10, 2);
        $sec = substr($a, 12, 2);
        return mktime($hour, $min, $sec, $month, $day, $year);
    }


